<template><view class="page"><view class="hero"><text class="title">考试复习</text><text>今日已完成 {{ overview.completedToday || 0 }} 次 · 待复习 {{ overview.dueCount || 0 }} 张</text><view class="heatmap"><view v-for="day in days" :key="day.date" :class="['day', level(day.count)]" /></view></view><view v-if="card" class="card"><text class="progress">学习进度 {{ card.progress.completed }} / {{ card.progress.required }} 次有效回忆</text><text class="question">{{ card.question }}</text><button v-if="!showAnswer" @click="showAnswer=true">显示答案</button><view v-else><text class="answer">{{ card.answer }}</text><text v-if="card.aiSummary" class="summary">{{ card.aiSummary }}</text><view class="actions"><button @click="rate('again')">Again</button><button @click="rate('hard')">Hard</button><button @click="rate('good')">Good</button><button @click="rate('easy')">Easy</button></view></view></view><view v-else class="empty">暂无待复习卡片，明天再来看看。</view></view></template>
<script setup>
import { computed, ref } from 'vue'; import { onShow } from '@dcloudio/uni-app'; import { getNextReviewCard, getReviewOverview, rateReviewCard } from '@/api/exam/review';
const overview=ref({}), card=ref(null), showAnswer=ref(false); const days=computed(()=>{const map=Object.fromEntries((overview.value.heatmap||[]).map(x=>[x.date,x.count]));return Array.from({length:84},(_,i)=>{const d=new Date();d.setDate(d.getDate()-83+i);const date=d.toISOString().slice(0,10);return {date,count:map[date]||0}})}); const level=n=>n>=30?'max':n>=20?'high':n>=10?'mid':n?'low':'';
async function load(){overview.value=(await getReviewOverview()).data||{};card.value=(await getNextReviewCard()).data||null;showAnswer.value=false} async function rate(value){await rateReviewCard(card.value.cardId,value);await load()} onShow(()=>load().catch(()=>{}));
</script>
<style scoped>.page{min-height:100vh;background:#f5f7fb;padding:28rpx 30rpx}.hero,.card,.empty{background:#fff;border-radius:22rpx;padding:30rpx}.hero{background:#17275e;color:#dce5ff}.title,.question{display:block;font-size:34rpx;font-weight:700;color:#fff}.hero text:not(.title){display:block;margin-top:12rpx;font-size:22rpx}.heatmap{display:grid;grid-template-columns:repeat(12,1fr);gap:7rpx;margin-top:28rpx}.day{height:20rpx;background:#445276;border-radius:4rpx}.low{background:#7593dc}.mid{background:#5272cb}.high{background:#3556d4}.max{background:#fff}.card{margin-top:24rpx}.progress,.summary{display:block;color:#748198;font-size:22rpx;margin-bottom:22rpx}.question{color:#25324a;line-height:1.6;margin-bottom:30rpx}.answer{display:block;white-space:pre-line;line-height:1.8;font-size:25rpx;color:#344158}.summary{margin-top:24rpx;line-height:1.7}.actions{display:flex;gap:10rpx;margin-top:26rpx}.actions button{flex:1;font-size:22rpx}.actions button:nth-child(1){color:#d44}.actions button:nth-child(4){color:#286}.empty{text-align:center;color:#8b96a8;margin-top:24rpx}</style>
